/* From Uiverse.io by vinodjangid07  - Tags: simple, animation, button, hover, hover effect, print */
.__UIV_SCOPE__ .print-btn {
  width: 100px;
  height: 45px;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: white;
  border: 1px solid rgb(213, 213, 213);
  border-radius: 10px;
  gap: 10px;
  font-size: 16px;
  cursor: pointer;
  overflow: hidden;
  font-weight: 500;
  box-shadow: 0px 10px 10px rgba(0, 0, 0, 0.065);
  transition: all 0.3s;
}
.__UIV_SCOPE__ .printer-wrapper {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 100%;
}
.__UIV_SCOPE__ .printer-container {
  height: 50%;
  width: 100%;
  display: flex;
  align-items: flex-end;
  justify-content: center;
}

.__UIV_SCOPE__ .printer-container svg {
  width: 100%;
  height: auto;
  transform: translateY(4px);
}
.__UIV_SCOPE__ .printer-page-wrapper {
  width: 100%;
  height: 50%;
  display: flex;
  align-items: flex-start;
  justify-content: center;
}
.__UIV_SCOPE__ .printer-page {
  width: 70%;
  height: 10px;
  border: 1px solid black;
  background-color: white;
  transform: translateY(0px);
  transition: all 0.3s;
  transform-origin: top;
}
.__UIV_SCOPE__ .print-btn:hover .printer-page {
  height: 16px;
  background-color: rgb(239, 239, 239);
}
.__UIV_SCOPE__ .print-btn:hover {
  background-color: rgb(239, 239, 239);
}
